def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    aggressive_count = 0
    weak_count = 0
    rich_count = 0

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
                weak_count += 1
            if opp.get('budget', 0) >= 700:
                rich_count += 1
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= 90:
                    aggressive_count += 1

    if not alive:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1
    high_supply = supply >= 22
    low_supply = supply <= 17

    if urgent:
        target = max(92.0, highest_prev + 3.0)
        if low_supply:
            target += 8.0
        return float(min(budget, target))

    if high_supply and hp >= 5 and no_water_days == 0:
        target = 16.0
        if aggressive_count == 0 and avg_prev < 60:
            target = 24.0
        return float(min(budget, target))

    if low_supply:
        if highest_prev >= 110:
            target = 36.0 if hp >= 6 and no_water_days == 0 else 88.0
        elif highest_prev >= 85:
            target = 54.0 if hp >= 6 else 82.0
        else:
            target = max(58.0, highest_prev + 2.5)
        if rich_count >= 1:
            target += 4.0
        return float(min(budget, target))

    target = 0.0
    if highest_prev >= 120:
        target = 28.0 if hp >= 6 and no_water_days == 0 else 86.0
    elif highest_prev >= 95:
        target = 34.0 if hp >= 6 else 74.0
    elif highest_prev >= 70:
        target = max(46.0, highest_prev * 0.72)
    elif highest_prev > 0:
        target = max(38.0, highest_prev + 1.5)
    else:
        target = 42.0

    if pressured:
        target += 10.0
    if weak_count >= 2 and hp >= 5 and no_water_days == 0:
        target -= 6.0

    remaining_days = max(0, 10 - int(day))
    reserve = remaining_days * 18.0
    if budget - target < reserve and not pressured:
        target = max(20.0, min(target, budget - reserve))

    if target < 0:
        target = 0.0
    return float(min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and read yesterday trace
    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents alive, bid conservatively
    if not alive_opponents:
        return float(min(my_status['budget'], DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    yesterday_bids = []
    yesterday_pressures = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev:
            bid = prev.get('bid', None)
            if bid is not None:
                yesterday_bids.append(float(bid))
            # Use hp_after/status as a pressure proxy if available
            hp_after = prev.get('hp_after', None)
            status = prev.get('status', None)
            if hp_after is not None:
                try:
                    yesterday_pressures.append((float(hp_after), status))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Decide aggressiveness based on yesterday's maximum bid
    # If someone was willing to spend near/above our daily salary, they likely overbid again.
    # We respond with a mid bid to avoid burning budget, but still compete.
    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Supply-based baseline: with supply in [15,25], number of full water units is 1 or 2.
    # We assume others will fight for 2 units when supply is high.
    supply_units = int(supply // float(WATER_REQ))
    if supply_units < 1:
        supply_units = 1
    if supply_units > 2:
        supply_units = 2

    # Baseline bid levels
    if supply_units == 2:
        baseline = DAILY_SALARY * 0.62
    else:
        baseline = DAILY_SALARY * 0.48

    # Pressure adjustment using yesterday highest bid
    # Thresholds tuned to the observed yesterday bids (~100-140)
    if highest_prev_bid >= DAILY_SALARY * 1.15:
        # Opponent(s) were extremely aggressive; increase bid to secure water this day.
        if my_hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.95
        else:
            target = DAILY_SALARY * 0.78
    elif highest_prev_bid >= DAILY_SALARY * 0.85:
        # Moderate aggression from others.
        if my_hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.82
        else:
            target = baseline + (DAILY_SALARY * 0.12)
    else:
        # Others were not too aggressive; keep bid near baseline.
        if my_hp <= 2.0 or no_water_days >= 2:
            target = DAILY_SALARY * 0.72
        else:
            target = baseline

    # Ensure we don't overbid beyond budget; also keep some reserve
    # Reserve fraction increases when our hp is low.
    if my_hp <= 2.0:
        reserve_frac = 0.15
    else:
        reserve_frac = 0.25

    max_affordable = max(0.0, my_budget * (1.0 - reserve_frac))
    bid = float(min(max_affordable, target))

    # Final guard: if budget is tiny, bid whatever we can.
    if bid <= 0.0:
        bid = float(min(my_budget, DAILY_SALARY * 0.3))

    return bid

def get_bid(day_context, my_status, opponents_status):
